style.css:
@-moz-document domain("canva.com") {
/* Genel arka plan ve yazı renkleri */
  body {
    background-color: #121212 !important;
    color: #e0e0e0 !important;
  }

  /* Üst, alt ve yan paneller */
  .header, .footer, .sidebar, .panel, .toolbar {
    background-color: #1e1e1e !important;
    color: #e0e0e0 !important;
  }

  /* Ana içerik alanı */
  .main-content, .canvas-container {
    background-color: #181818 !important;
    color: #ffffff !important;
  }

  /* Butonlar */
  button, a {
    background-color: #333333 !important;
    color: #e0e0e0 !important;
    border: 1px solid #444444 !important;
  }

  button:hover, a:hover {
    background-color: #444444 !important;
    color: #ffffff !important;
  }

  /* Giriş kutuları */
  input, textarea {
    background-color: #292929 !important;
    color: #ffffff !important;
    border: 1px solid #555555 !important;
  }

  /* Kenar çubukları ve menüler */
  .menu, .dropdown, .sidebar-panel {
    background-color: #202020 !important;
    color: #e0e0e0 !important;
  }

  /* Simgeler ve ikonlar */
  .icon, .icon-button {
    background-color: transparent !important;
    color: #e0e0e0 !important;
  }
}
